#include "civic/cadastre/Cadastre.hpp"
#include <cmath>
namespace civic::cadastre {
std::uint64_t stable_id_from_key(std::string_view key) noexcept {std::uint64_t h=1469598103934665603ULL;for(unsigned char c:key){h^=c;h*=1099511628211ULL;}return h==0?1:h;}
civic::core::Result<void> CadastralGraph::insert(Parcel p) noexcept {if(p.id.value()==0||p.external_id.empty())return std::unexpected(civic::core::error(civic::core::ErrorCode::invalid_argument,"parcel id required"));if(parcels_.contains(p.id))return std::unexpected(civic::core::error(civic::core::ErrorCode::conflict,"duplicate parcel id"));auto canon=civic::geometry::canonicalize(p.boundary);if(!canon)return std::unexpected(canon.error());p.boundary=*canon;p.area_m2=civic::geometry::area_square_meters(p.boundary);auto c=civic::geometry::centroid(p.boundary);if(!c)return std::unexpected(c.error());p.centroid=*c;parcels_.emplace(p.id,std::move(p));++revision_;return {};}
civic::core::Result<void> CadastralGraph::validate() const noexcept {std::set<std::string> external;for(const auto&[id,p]:parcels_){if(id.value()==0||p.external_id.empty()||!external.insert(p.external_id).second)return std::unexpected(civic::core::error(civic::core::ErrorCode::invariant_failure,"duplicate or invalid parcel identity"));if(p.live){auto canon=civic::geometry::canonicalize(p.boundary);if(!canon||civic::geometry::area_square_meters(*canon)<=0)return std::unexpected(civic::core::error(civic::core::ErrorCode::invariant_failure,"invalid parcel boundary"));for(auto parent:p.historical_parent_ids)if(parent==id)return std::unexpected(civic::core::error(civic::core::ErrorCode::invariant_failure,"lineage self-cycle"));}}for(const auto&[_,e]:easements_)for(auto id:e.parcel_ids)if(!parcels_.contains(id))return std::unexpected(civic::core::error(civic::core::ErrorCode::invariant_failure,"easement references missing parcel"));return {};}
civic::core::Result<void> CadastreTransaction::commit() noexcept {auto validation=staged_.validate();if(!validation)return validation;target_=std::move(staged_);++target_.revision_;committed_=true;return {};}
}
